const fs = require('fs-extra');
const path = require('path');

const outputProtoDefineFileName = "LuaProtos.lua"
const outputProtoInfoFileName = "LuaProtocols.lua"
const outputProtoEmitorFileName = "IProtocolFacade.lua"

const protoKeys = ["Request", "Response", "Notify", "NotifyAll", "NotifySpecific"]



function validateFormat(item) {

    var hasNotify = item.Notify || item.NotifyAll || item.NotifySpecific

    if (item.Request && hasNotify) {
        throw new Error(`proto ${item.ProtoName} 不能同时定义Request和Notify`)
    }

    if (item.Response && hasNotify) {
        throw new Error(`proto ${item.ProtoName} 不能同时定义Response和Notify`)
    }

    if (!item.Request && !item.Response && !hasNotify) {
        throw new Error(`proto ${item.ProtoName} 必须定义Request, Response, Notify中的一个`)
    }

    if (!item.Request && item.Response) {
        throw new Error(`proto ${item.ProtoName} 不能定义Response, 但未定义Request`)
    }

    // Notify NotifyAll NotifySpecific 只能有一个
    var notifyCount = 0
    for (var key of ["Notify", "NotifyAll", "NotifySpecific"]) {
        if (item[key]) {
            notifyCount++
        }
    }
    if (notifyCount > 1) {
        throw new Error(`proto ${item.ProtoName} 不能同时定义Notify, NotifyAll, NotifySpecific`)
    }
}


function buildProtoInterfaces(config) {
    var content = ""
    for (var rbxPath in config) {
        var item = config[rbxPath]
        validateFormat(item)
        for (var key of protoKeys) {
            if (item[key]) {
                content += `export type ${item.ProtoName
                    }${key} = ${item[key]} \n`
            }
        }
    }
    return content
}


function buildProtoInfos(config) {

    var content = "return {\n"
    for (var rbxPath in config) {
        var item = config[rbxPath]
        validateFormat(item)
        if (item.Request && item.Response) {
            content += `    ${item.ProtoName} = {Type="rpc"},\n`
        } else if (item.Request && !item.Response) {
            content += `    ${item.ProtoName} = {Type="submit"},\n`
        } else if (item.Notify) {
            content += `    ${item.ProtoName} = {Type="notify"},\n`
        } else if (item.NotifyAll) {
            content += `    ${item.ProtoName} = {Type="notifyAll"},\n`
        } else if (item.NotifySpecific) {
            content += `    ${item.ProtoName} = {Type="notifySpecific"},\n`
        }
    }
    content += "}\n"
    return content
}

function _createEventHandler(protoName, dotType, responseType, isSpecific) {
    return `(dto:${dotType}${isSpecific ? ",player:Player" : ""})${responseType ? `:${responseType}` : ""}\n` +
        `    return self.ProtocolEmiter:EmitProtocol("${protoName}",dto${isSpecific ? ",player" : ""})\n` +
        `end
        `
}

function buildProtoEmitor(config) {

    var content = `local module = {}
module.__index = module

function module.new(protocolEmiter: IProtocolEmiter)
	local self = setmetatable({}, module)
	self.ProtocolEmiter = protocolEmiter
	return self
end

`
    for (var rbxPath in config) {
        var item = config[rbxPath]
        validateFormat(item)
        if (item.Request && item.Response) {
            content += `function module:${item.ProtoName}_InvokeServer${_createEventHandler(item.ProtoName, item.ProtoName + `Request`, item.ProtoName + `Response`)}\n`
        } else if (item.Request && !item.Response) {
            content += `function module:${item.ProtoName}_FireServer${_createEventHandler(item.ProtoName, item.ProtoName + `Request`)}\n`
        } else if (item.Notify) {
            content += `function module:${item.ProtoName}_FireClient${_createEventHandler(item.ProtoName, item.ProtoName + `Notify`)}\n`
        } else if (item.NotifyAll) {
            content += `function module:${item.ProtoName}_FireAllClients${_createEventHandler(item.ProtoName, item.ProtoName + `NotifyAll`)}\n`
        } else if (item.NotifySpecific) {
            content += `function module:${item.ProtoName}_FireSpecificClient${_createEventHandler(item.ProtoName, item.ProtoName + `NotifySpecific`, undefined, true)}\n`
        }

    }
    content += "return module\n"
    return content

}

function gen(config, outputPath, outputRobloxManifest) {
    fs.ensureDirSync(outputRobloxManifest);
    fs.ensureDirSync(outputPath);
    // 生成接口定义
    var interfaces = buildProtoInterfaces(config)
    fs.writeFileSync(path.join(outputPath, outputProtoDefineFileName), interfaces);

    // 生成信息定义
    var infos = buildProtoInfos(config)
    fs.writeFileSync(path.join(outputRobloxManifest, outputProtoInfoFileName), infos);

    var extensionsPath = path.join(outputRobloxManifest, "Extensions")
    fs.ensureDirSync(extensionsPath);

    // 生成发射器定义
    var emitor = buildProtoEmitor(config)
    fs.writeFileSync(path.join(extensionsPath, outputProtoEmitorFileName), emitor);


    console.log(`write file ${path.join(outputPath, outputProtoDefineFileName)} `)
    console.log(`write file ${path.join(outputRobloxManifest, outputProtoInfoFileName)} `)
}


module.exports = gen;